var _vpBarStyled=false;
function vpEnsureBarStyle(){
  if(_vpBarStyled)return;_vpBarStyled=true;
  var st=document.createElement('style');
  st.textContent='@keyframes vpPulse{0%,100%{opacity:1}50%{opacity:.4}}#vpVoiceBar .vpdot{width:9px;height:9px;border-radius:50%;background:#fff;flex:none;animation:vpPulse 1.1s infinite}';
  document.head.appendChild(st);
}
function vpUnlockSpeech(){
  try{
    if(!window.speechSynthesis)return;
    window.speechSynthesis.resume();
    var u=new SpeechSynthesisUtterance(' ');
    u.volume=0.01;u.rate=10;u.lang='pt-BR';
    window.speechSynthesis.speak(u);
  }catch(e){}
}
function vpOpenConversation(){
  vpUnlockSpeech();
  if(document.getElementById('vpVoiceBar'))return;
  vpEnsureBarStyle();
  var history=[];
  var active=true;
  var cancelListen=null;
  var bar=document.createElement('div');
  bar.id='vpVoiceBar';
  bar.style.cssText='position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:99999;background:rgba(15,20,30,.94);color:#fff;padding:11px 12px 11px 18px;border-radius:30px;font-size:.86rem;display:flex;align-items:center;gap:12px;box-shadow:0 8px 26px rgba(0,0,0,.35);max-width:90vw;font-family:inherit';
  bar.innerHTML='<span class="vpdot"></span><span id="vpVoiceBarText" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:64vw">Ouvindo...</span><button id="vpVoiceBarStop" type="button" style="background:rgba(255,255,255,.16);border:none;color:#fff;border-radius:50%;width:26px;height:26px;flex:none;font-size:.85rem;cursor:pointer;line-height:1">✕</button>';
  document.body.appendChild(bar);
  var txt=document.getElementById('vpVoiceBarText');
  var stopBtn=document.getElementById('vpVoiceBarStop');
  function setTxt(t){if(txt)txt.textContent=t;}
  function stopAll(){
    active=false;
    if(cancelListen){cancelListen();cancelListen=null;}
    try{window.speechSynthesis&&window.speechSynthesis.cancel();}catch(e){}
    if(bar&&bar.parentNode)bar.parentNode.removeChild(bar);
  }
  if(stopBtn)stopBtn.onclick=stopAll;
  function listenTurn(){
    if(!active)return;
    if(typeof vpListenOnce!=='function'){setTxt('Voz não disponível neste aparelho');setTimeout(stopAll,2200);return;}
    setTxt('Ouvindo...');
    cancelListen=vpListenOnce(function(transcript){
      cancelListen=null;
      if(!active)return;
      if(!transcript){setTxt('Não ouvi nada...');setTimeout(function(){if(active)listenTurn();},900);return;}
      setTxt('"'+transcript+'"');
      history.push({role:'user',text:transcript});
      setTimeout(function(){if(active)setTxt('Pensando...');},700);
      vpAskAI(transcript,history).then(function(answer){
        if(!active)return;
        history.push({role:'assistant',text:answer});
        setTxt(answer);
        vpSpeakForceCb(answer,function(){if(active)listenTurn();});
      }).catch(function(err){
        if(!active)return;
        var msg=vpErrMsg(err);
        setTxt(msg);
        vpSpeakForceCb(msg,function(){if(active)listenTurn();});
      });
    },function(err){
      cancelListen=null;
      if(!active)return;
      var msg=(err&&err.error==='timeout')?'Não ouvi nada...':(err&&err.error==='no-speech')?'Não ouvi fala...':(err&&err.error==='not-allowed')?'Permissão de microfone negada':'Não consegui ouvir';
      setTxt(msg);
      if(err&&err.error==='not-allowed'){setTimeout(stopAll,2500);return;}
      setTimeout(function(){if(active)listenTurn();},900);
    });
  }
  listenTurn();
}
function vpSpeakForce(text){vpSpeakQueue(text,null,true);}
function vpListenOnce(onResult,onError){
  try{
    var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SR){toast('Reconhecimento de voz não disponível neste navegador/aparelho',false);if(onError)onError();return function(){};}
    var r=new SR();
    var done=false;
    r.lang='pt-BR';r.continuous=false;r.interimResults=false;r.maxAlternatives=1;
    var timer=setTimeout(function(){
      if(done)return;done=true;
      try{r.abort();}catch(e){}
      if(onError)onError({error:'timeout'});
    },6000);
    function finish(fn,arg){if(done)return;done=true;clearTimeout(timer);try{fn(arg);}catch(e){}}
    r.onresult=function(e){
      var t=(e.results&&e.results[0]&&e.results[0][0])?e.results[0][0].transcript:'';
      finish(onResult,t||'');
    };
    r.onerror=function(e){finish(onError,e);};
    r.onend=function(){finish(onError,{error:'no-speech'});};
    try{r.start();}catch(e){finish(onError,e);}
    return function cancel(){if(done)return;done=true;clearTimeout(timer);try{r.abort();}catch(e){}};
  }catch(e){if(onError)onError(e);return function(){};}
}
