 +'@media(max-width:1000px){#v-home .ha-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){#v-home .ha-grid{grid-template-columns:1fr}.alertTop{width:36px;height:36px}}';document.head.appendChild(css);
