 var top=document.querySelector('.topbar'),user=document.getElementById('userBtn');if(top&&user&&!document.getElementById('alertTop')){var bt=document.createElement('button');bt.id='alertTop';bt.className='alertTop';bt.title='Central de Alertas';bt.innerHTML='⚠<span class="ab"></span>';bt.onclick=window.abrirAlertas;top.insertBefore(bt,user);}
 var baseHome=renderHome;renderHome=function(){baseHome();var v=document.getElementById('v-home'),bottom=v&&v.querySelector('.hx-bottom');if(!v||!bottom)return;var as=dados(),ativos=as.filter(function(a){return a.n>0;}),box=document.createElement('div');box.className='ha-box';box.innerHTML='<div class="ha-head"><h3>Central de Alertas</h3><span>Atualização automática · '+new Date().toLocaleTimeString('pt-BR')+'</span></div>'+(ativos.length?'<div class="ha-grid">'+as.map(function(a){return '<div class="ha-card" data-ha="'+a.view+'" style="--ac:'+a.cor+'"><b>'+a.n+'</b><span>'+a.titulo+'</span><small>'+a.desc+'</small></div>';}).join('')+'</div>':'<div class="ha-ok">✓ Operação sem alertas neste momento.</div>');v.insertBefore(box,bottom);box.querySelectorAll('[data-ha]').forEach(function(c){c.onclick=function(){go(c.dataset.ha);};});atualizaBadge();};window.renderHome=renderHome;
